package com.deathcounter;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.CommandExecuted;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.OverlayMenuClicked;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
		name = "Death Counter",
		description = "Tracks how many times you have died and shows the total in a movable overlay",
		tags = {"death", "counter", "deaths", "overlay", "tracker"},
		configName = "DeathCounterPlugin"
)
public class DeathCounterPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private DeathCounterConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private DeathCounterOverlay overlay;

	@Getter
	private int deaths;

	// All-time total; incremented alongside deaths but never cleared by the per-session resets.
	@Getter
	private int allTimeDeaths;

	// True once we've seen LOGGING_IN, so the following LOGGED_IN is a real login and not a world hop.
	private boolean loginPending;

	// Armed on a client-open reset so the first login afterwards doesn't reset the counter a second time.
	private boolean skipNextLoginReset;

	@Override
	protected void startUp() throws Exception
	{
		deaths = loadDeaths();
		allTimeDeaths = loadAllTimeDeaths();
		loginPending = false;
		skipNextLoginReset = false;
		overlayManager.add(overlay);
		log.debug("Death Counter started with {} deaths ({} all-time)", deaths, allTimeDeaths);

		if (config.resetOnClientOpen())
		{
			resetDeaths();
			// A client start always follows a logout, so suppress the next login reset to avoid a double reset.
			skipNextLoginReset = config.resetOnLogin();
			log.debug("Death count reset on client open");
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		log.debug("Death Counter stopped");
	}

	@Subscribe
	public void onActorDeath(ActorDeath actorDeath)
	{
		if (actorDeath.getActor() == client.getLocalPlayer())
		{
			incrementDeaths();
			log.debug("Local player died, death count now {} ({} all-time)", deaths, allTimeDeaths);
		}
	}

	@Subscribe
	public void onCommandExecuted(CommandExecuted event)
	{
		// Dev helper: "::dcadd" bumps the counter without needing to actually die.
		if ("dcadd".equalsIgnoreCase(event.getCommand()))
		{
			incrementDeaths();
			log.debug("::dcadd, death count now {} ({} all-time)", deaths, allTimeDeaths);
		}
	}

	private void incrementDeaths()
	{
		deaths++;
		allTimeDeaths++;
		saveDeaths(deaths);
		saveAllTimeDeaths(allTimeDeaths);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		switch (event.getGameState())
		{
			case LOGGING_IN:
				// Marks an actual login attempt; world hops go through HOPPING instead, so they won't trigger a reset.
				loginPending = true;
				break;
			case LOGGED_IN:
				if (loginPending)
				{
					loginPending = false;
					handleLogin();
				}
				break;
			default:
				break;
		}
	}

	private void handleLogin()
	{
		if (!config.resetOnLogin())
		{
			return;
		}

		if (skipNextLoginReset)
		{
			skipNextLoginReset = false;
			log.debug("Skipping login reset; counter was already reset on client open");
			return;
		}

		resetDeaths();
		log.debug("Death count reset on login");
	}

	@Subscribe
	public void onOverlayMenuClicked(OverlayMenuClicked event)
	{
		if (event.getOverlay() == overlay
			&& DeathCounterOverlay.RESET_OPTION.equals(event.getEntry().getOption()))
		{
			resetDeaths();
		}
	}

	private void resetDeaths()
	{
		deaths = 0;
		saveDeaths(0);
		log.debug("Death count reset to 0");
	}

	private int loadDeaths()
	{
		Integer stored = configManager.getConfiguration(
			DeathCounterConfig.GROUP, DeathCounterConfig.DEATHS_KEY, int.class);
		return stored == null ? 0 : stored;
	}

	private void saveDeaths(int value)
	{
		configManager.setConfiguration(DeathCounterConfig.GROUP, DeathCounterConfig.DEATHS_KEY, value);
	}

	private int loadAllTimeDeaths()
	{
		Integer stored = configManager.getConfiguration(
			DeathCounterConfig.GROUP, DeathCounterConfig.ALL_TIME_DEATHS_KEY, int.class);
		return stored == null ? 0 : stored;
	}

	private void saveAllTimeDeaths(int value)
	{
		configManager.setConfiguration(DeathCounterConfig.GROUP, DeathCounterConfig.ALL_TIME_DEATHS_KEY, value);
	}

	@Provides
	DeathCounterConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DeathCounterConfig.class);
	}
}

package com.deathcounter;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(DeathCounterConfig.GROUP)
public interface DeathCounterConfig extends Config
{
	String GROUP = "death-counter";
	String DEATHS_KEY = "deaths";
	String ALL_TIME_DEATHS_KEY = "allTimeDeaths";

	@ConfigItem(
		keyName = "counterLabel",
		name = "Counter label",
		description = "Text shown in front of the session death count",
		position = 0
	)
	default String counterLabel()
	{
		return "Deaths";
	}

	@ConfigItem(
		keyName = "showAllTimeDeaths",
		name = "Show all-time deaths",
		description = "Show a second line with the all-time death total, which is never reset by the per-session resets",
		position = 1
	)
	default boolean showAllTimeDeaths()
	{
		return true;
	}

	@ConfigItem(
		keyName = "allTimeLabel",
		name = "All-time label",
		description = "Text shown in front of the all-time death count",
		position = 2
	)
	default String allTimeLabel()
	{
		return "All-time deaths";
	}

	@ConfigItem(
		keyName = "resetOnClientOpen",
		name = "Reset on client open",
		description = "Reset the session death counter each time the client starts up",
		position = 3
	)
	default boolean resetOnClientOpen()
	{
		return false;
	}

	@ConfigItem(
		keyName = "resetOnLogin",
		name = "Reset on login",
		description = "Reset the session death counter each time you log in. On client startup this is skipped when 'Reset on client open' has already reset the counter, so it is not reset twice.",
		position = 4
	)
	default boolean resetOnLogin()
	{
		return false;
	}
}

package com.deathcounter;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.BackgroundComponent;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.TextComponent;

class DeathCounterOverlay extends Overlay
{
	static final String RESET_OPTION = "Reset";

	private static final int BORDER = ComponentConstants.STANDARD_BORDER;
	private static final int GAP = 6;
	private static final int MAX_LABEL_WIDTH = 120;

	private final DeathCounterPlugin plugin;
	private final DeathCounterConfig config;

	private final BackgroundComponent background = new BackgroundComponent();

	@Inject
	private DeathCounterOverlay(DeathCounterPlugin plugin, DeathCounterConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setMovable(true);
		setPosition(OverlayPosition.TOP_LEFT);
		getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY, RESET_OPTION, "Death Counter"));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final FontMetrics fm = graphics.getFontMetrics();
		final int lineHeight = fm.getHeight();

		final List<Row> rows = new ArrayList<>();
		rows.add(buildRow(config.counterLabel(), plugin.getDeaths(), fm));
		if (config.showAllTimeDeaths())
		{
			rows.add(buildRow(config.allTimeLabel(), plugin.getAllTimeDeaths(), fm));
		}

		int contentWidth = 0;
		int contentHeight = 0;
		for (final Row row : rows)
		{
			contentWidth = Math.max(contentWidth, row.labelWidth + GAP + row.countWidth);
			contentHeight += row.labelLines.size() * lineHeight;
		}

		final int width = BORDER * 2 + contentWidth;
		final int height = BORDER * 2 + contentHeight;

		background.setRectangle(new Rectangle(0, 0, width, height));
		background.render(graphics);

		int rowTop = BORDER;
		for (final Row row : rows)
		{
			final int rowHeight = row.labelLines.size() * lineHeight;

			int baseline = rowTop + fm.getAscent();
			for (final String line : row.labelLines)
			{
				final TextComponent lineText = new TextComponent();
				lineText.setText(line);
				lineText.setPosition(new Point(BORDER, baseline));
				lineText.render(graphics);
				baseline += lineHeight;
			}

			final int countBaseline = rowTop + fm.getAscent() + (rowHeight - lineHeight) / 2;
			final TextComponent countText = new TextComponent();
			countText.setText(row.count);
			countText.setPosition(new Point(width - BORDER - row.countWidth, countBaseline));
			countText.render(graphics);

			rowTop += rowHeight;
		}

		return new Dimension(width, height);
	}

	private Row buildRow(String label, int value, FontMetrics fm)
	{
		final List<String> labelLines = wrap(label, fm, MAX_LABEL_WIDTH);
		int labelWidth = 0;
		for (final String line : labelLines)
		{
			labelWidth = Math.max(labelWidth, fm.stringWidth(line));
		}

		final String count = Integer.toString(value);
		return new Row(labelLines, labelWidth, count, fm.stringWidth(count));
	}

	private static final class Row
	{
		private final List<String> labelLines;
		private final int labelWidth;
		private final String count;
		private final int countWidth;

		Row(List<String> labelLines, int labelWidth, String count, int countWidth)
		{
			this.labelLines = labelLines;
			this.labelWidth = labelWidth;
			this.count = count;
			this.countWidth = countWidth;
		}
	}

	private static List<String> wrap(String text, FontMetrics fm, int maxWidth)
	{
		final List<String> lines = new ArrayList<>();
		if (text == null || text.isEmpty())
		{
			lines.add("");
			return lines;
		}

		if (fm.stringWidth(text) <= maxWidth)
		{
			lines.add(text);
			return lines;
		}

		final StringBuilder current = new StringBuilder();
		for (final String word : text.split(" "))
		{
			if (current.length() == 0)
			{
				current.append(word);
			}
			else if (fm.stringWidth(current + " " + word) <= maxWidth)
			{
				current.append(' ').append(word);
			}
			else
			{
				lines.add(current.toString());
				current.setLength(0);
				current.append(word);
			}
		}

		if (current.length() > 0)
		{
			lines.add(current.toString());
		}

		return lines;
	}
}
